import{_ as i,o,c as t,a2 as a}from"./chunks/framework.DHmNT4rz.js";const h=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1784470733000}'),r={name:"guide/security.md"};function s(n,e,d,l,c,u){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><p>The codebase includes tenant-scoped procedures, hashed and scoped API keys, session and platform policies, Redis-backed security rate limits, bounded request bodies, CSP and baseline response headers, webhook signature verification, DNS-pinned outbound webhook requests, sanitized logs, and production container hardening. Production Compose runs application containers read-only with dropped Linux capabilities and resource limits.</p><h2 id="what-is-covered" tabindex="-1">What is covered <a class="header-anchor" href="#what-is-covered" aria-label="Permalink to &quot;What is covered&quot;">​</a></h2><ul><li>Tenant-scoped procedures so a request cannot read another workspace&#39;s data</li><li>API keys stored hashed and scoped, never in plaintext</li><li>Session and platform-operator policies, including an impersonation policy</li><li>Redis-backed rate limiting on security-sensitive routes</li><li>Bounded request bodies and a baseline of response headers, including CSP</li><li>Webhook signature verification on inbound events</li><li>DNS-pinned outbound webhook delivery to resist SSRF against internal hosts</li><li>Log sanitization to keep secrets out of structured logs</li><li>Read-only application containers with dropped capabilities in production</li></ul><h2 id="what-remains-your-responsibility" tabindex="-1">What remains your responsibility <a class="header-anchor" href="#what-remains-your-responsibility" aria-label="Permalink to &quot;What remains your responsibility&quot;">​</a></h2><p>These controls are a foundation, not a substitute for deployment-specific review. Configure TLS, managed secrets, backups and point-in-time recovery, object-store versioning, alerting, and provider credentials for your environment.</p><div class="warning custom-block"><p class="custom-block-title">Review before exposing a deployment</p><p>Read <a href="https://github.com/mathias7799/SaaSWeave/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> before exposing a deployment publicly. Security vulnerabilities must follow the private reporting process described there, not a public issue.</p></div>',7)])])}const b=i(r,[["render",s]]);export{h as __pageData,b as default};
